import re, subprocess
from playwright.sync_api import sync_playwright, expect
B="http://localhost:3000"; probs=[]
def ok(m): print("✓", m, flush=True)
def sql(q): return subprocess.run(["psql","-h","/tmp","-p","5433","-U","postgres","-d","dyas_e2e","-tAc",q],capture_output=True,text=True,check=True).stdout.strip()
with sync_playwright() as p:
    b=p.chromium.launch(executable_path="/usr/bin/google-chrome", args=["--no-sandbox"])
    def ctx(w=390,h=844,mobile=True,geo=None,ask=False):
        extra={"geolocation":geo,"permissions":["geolocation"]} if geo else {}
        c=b.new_context(viewport={"width":w,"height":h}, is_mobile=mobile, has_touch=mobile, locale="ro-RO", timezone_id="Europe/Bucharest", **extra)
        if geo: c.add_init_script("try{localStorage.setItem('dyas.push','no:'+Date.now())}catch(e){}")
        if not ask and not geo: c.add_init_script("try{localStorage.getItem('dyas.loc')||localStorage.setItem('dyas.loc','no:'+Date.now());localStorage.getItem('dyas.push')||localStorage.setItem('dyas.push','no:'+Date.now())}catch(e){}")
        pg=c.new_page(); pg.set_default_timeout(15000)
        pg.on("pageerror", lambda e: probs.append(f"pageerror {e}"))
        pg.on("console", lambda m: m.type=="error" and not re.search(r"WebSocket|realtime|Failed to load resource", m.text) and probs.append(m.text))
        pg.on("dialog", lambda d: d.accept())
        return pg
    def signup(pg, email, firm, name):
        pg.goto(B+"/firma-noua-5lo4x0")
        pg.get_by_label("Email").fill(email); pg.get_by_label("Parolă").fill("parola1234"); pg.get_by_role("button", name="Creează cont").click()
        pg.wait_for_url(re.compile("/onboarding")); pg.get_by_role("tab", name="Înființez firma").click()
        pg.get_by_label("Numele firmei").fill(firm); pg.get_by_label("Numele tău").fill(name); pg.get_by_role("button", name="Creează firma").click()
        pg.wait_for_url(re.compile("/dashboard"))
    o=ctx(1280,900,False); signup(o,"dani@dyas.ro","Test srl","Dani")
    c=ctx(geo={"latitude":44.4805,"longitude":26.1298,"accuracy":12}); signup(c,"client@firma.ro","Client Construct SRL","Cristi")
    sql("insert into platform_owners(user_id) select id from auth.users where email='dani@dyas.ro'")
    ok("2 firme create; Dani setat proprietar")
    # clientul nu are acces
    c.goto(B+"/proprietar"); expect(c.get_by_role("heading", name="Acces restricționat")).to_be_visible()
    expect(c.get_by_role("link", name="Proprietar")).to_have_count(0)
    ok("adminul unei firme nu vede panoul (nici în meniu)")
    # proprietarul
    o.goto(B+"/dashboard"); o.get_by_role("link", name="Proprietar").first.click()
    expect(o.get_by_role("heading", name="Panoul proprietarului")).to_be_visible()
    expect(o.get_by_text("Firme", exact=True).first).to_be_visible()
    o.wait_for_timeout(500); o.screenshot(path="shots/70_proprietar_prezentare.png", full_page=True)
    ok("prezentare: statistici platformă")
    o.get_by_role("tab", name="Firme").click()
    expect(o.get_by_text("Client Construct SRL")).to_be_visible(); expect(o.get_by_text("client@firma.ro", exact=False)).to_be_visible()
    o.get_by_text("Client Construct SRL").click()
    expect(o.get_by_text("Conturi (1)")).to_be_visible()
    o.get_by_label("Plan").select_option("proba"); o.get_by_label("Perioadă de probă până la").fill("2026-12-31")
    o.get_by_label("Notă internă (o vezi doar tu)").fill("A cerut demo, sună în decembrie"); o.get_by_role("button", name="Salvează").click()
    expect(o.get_by_text("Salvat.")).to_be_visible()
    o.screenshot(path="shots/71_proprietar_firme.png", full_page=True)
    assert sql("select plan||'|'||trial_until||'|'||owner_note from companies where name='Client Construct SRL'")=="proba|2026-12-31|A cerut demo, sună în decembrie"
    ok("plan, probă și notă internă salvate")
    o.get_by_role("button", name="Suspendă firma").click(); expect(o.get_by_role("button", name="Reactivează firma")).to_be_visible()
    c.goto(B+"/dashboard"); expect(c.get_by_role("heading", name="Contul firmei este suspendat")).to_be_visible()
    c.screenshot(path="shots/72_firma_suspendata.png"); ok("firmă suspendată → clientul vede mesajul de suspendare")
    o.get_by_role("button", name="Reactivează firma").click(); expect(o.get_by_role("button", name="Suspendă firma")).to_be_visible()
    c.goto(B+"/dashboard"); expect(c.get_by_role("heading", name="Contul firmei este suspendat")).to_have_count(0)
    expect(c.get_by_role("heading", name="Lucrări active")).to_be_visible(); ok("reactivare → clientul are din nou acces")
    # conectări
    n=int(sql("select count(*) from login_events")); assert n>=2, n
    o.get_by_role("tab", name="Conectări").click()
    expect(o.get_by_text(re.compile("Ultimele conectări"))).to_be_visible(); expect(o.get_by_text("Cristi").first).to_be_visible()
    o.screenshot(path="shots/73_proprietar_conectari.png", full_page=True); ok(f"conectări înregistrate și afișate ({n})")
    # activitatea adminului unei firme
    c.goto(B+"/lucrari?nou=1"); d=c.get_by_role("dialog"); d.get_by_label("Nume lucrare").fill("Vilă Snagov"); d.get_by_role("button", name="Adaugă lucrare").click(); c.wait_for_url(re.compile("/lucrari/"))
    c.get_by_role("button", name="Modifică").first.click(); d=c.get_by_role("dialog"); d.get_by_label("Localitate").fill("Snagov"); d.get_by_label("Client").fill("Familia Ionescu"); d.get_by_role("button", name="Salvează").click(); expect(d).to_be_hidden()
    o.goto(B+"/proprietar?tab=activitate"); expect(o.get_by_text("Cristi a adăugat lucrarea „Vilă Snagov”")).to_be_visible()
    expect(o.get_by_text(re.compile(r"Cristi a modificat lucrarea „Vilă Snagov” \((client, localitate|localitate, client)\)"))).to_be_visible()
    o.get_by_role("button", name="Vezi ce s-a schimbat").first.click(); expect(o.get_by_text("Familia Ionescu")).to_be_visible()
    o.screenshot(path="shots/76_proprietar_activitate.png", full_page=True); ok("activitatea arată elementul și câmpurile schimbate (înainte → după)")
    # utilizarea aplicației: la admin (pagina lui) și la proprietar (în fișa firmei)
    c.goto(B+"/utilizare"); expect(c.get_by_role("heading", name="Utilizare aplicație")).to_be_visible()
    expect(c.get_by_text("Folosește aplicația").first).to_be_visible(); expect(c.get_by_text("Au intrat azi")).to_be_visible()
    c.screenshot(path="shots/87_utilizare_admin.png", full_page=True); ok("adminul firmei vede utilizarea aplicației")
    o.goto(B+"/proprietar?tab=firme"); o.locator("main").get_by_role("button").filter(has_text="Client Construct SRL").first.click()
    o.get_by_role("button", name="Utilizarea aplicației").click(); expect(o.get_by_text("Persoane care au deschis aplicația, pe zile")).to_be_visible()
    ok("proprietarul vede utilizarea fiecărei firme")
    # adminul elimină / șterge un angajat; codul nou de acces
    c.goto(B+"/angajati"); c.get_by_role("button", name="Adaugă angajat").first.click(); d=c.get_by_role("dialog")
    d.get_by_label("Nume și prenume").fill("Vasile Pop"); d.get_by_label("Meserie").fill("Faianțar"); d.get_by_label("Telefon (WhatsApp)").fill("0733 444 555")
    d.get_by_role("button", name="Adaugă angajat").click(); expect(d).to_be_hidden()
    expect(c.get_by_text("Faianțar").first).to_be_visible(); ok("meseria apare ca etichetă în lista de angajați")
    c.get_by_text("Vasile Pop", exact=True).click(); c.get_by_role("button", name="Acces în aplicație").click(); d=c.get_by_role("dialog")
    d.get_by_role("button", name="Generează codul").click(); expect(d.locator("div.font-mono")).to_be_visible(); d.get_by_role("button", name="Gata").click()
    expect(c.get_by_role("button", name="Cod nou de acces")).to_be_visible(); ok("adminul generează cod de acces și poate genera altul nou")
    c.get_by_role("button", name="Elimină / șterge").click(); d=c.get_by_role("dialog"); d.get_by_role("button", name="Elimină angajatul").click(); expect(d).to_be_hidden()
    expect(c.get_by_text("Inactiv").first).to_be_visible(); expect(c.get_by_text("Fără acces").first).to_be_visible()
    assert sql("select count(*) from auth.users where email='t40733444555@telefon.dyasplanning.app'")=="0"
    ok("eliminare: inactiv, fără acces, contul de telefon șters")
    c.get_by_role("button", name="Elimină / șterge").click(); d=c.get_by_role("dialog"); d.get_by_text("Șterge definitiv").first.click()
    expect(d.get_by_role("button", name="Șterge definitiv")).to_be_disabled(); d.get_by_label(re.compile("Scrie numele pentru confirmare")).fill("Vasile Pop")
    d.screenshot(path="shots/89_sterge_angajat.png"); d.get_by_role("button", name="Șterge definitiv").click(); c.wait_for_url(re.compile(r"/angajati$"))
    assert sql("select count(*) from employees where full_name='Vasile Pop'")=="0"; ok("ștergere definitivă a angajatului")
    # conectări cu GPS + fișa utilizatorului + hartă
    o.goto(B+"/proprietar?tab=conectari"); expect(o.get_by_text(re.compile(r"44\.480(5|50), 26\.129(8|80)")).first).to_be_visible(); expect(o.get_by_text("(±12 m)").first).to_be_visible()
    o.screenshot(path="shots/83_conectari_gps.png", full_page=True); ok("conectarea are locația GPS exactă (±12 m)")
    o.locator("main").get_by_role("button", name="Cristi").first.click(); md=o.get_by_role("dialog")
    expect(md.get_by_text("Client Construct SRL").first).to_be_visible(); expect(md.get_by_text(re.compile(r"Dispozitive \(\d+\)"))).to_be_visible(); expect(md.get_by_text("Acțiuni ca administrator")).to_be_visible()
    o.screenshot(path="shots/84_fisa_utilizator.png", full_page=True); md.get_by_role("button", name="Închide").first.click(); ok("fișa utilizatorului: dispozitive, conectări, acțiuni")
    o.get_by_role("tab", name="Hartă").click(); expect(o.locator(".leaflet-container")).to_be_visible(); expect(o.locator("path.leaflet-interactive").first).to_be_attached()
    o.screenshot(path="shots/85_harta.png", full_page=True); ok("harta cu pozițiile")
    # fereastra de permisiune pentru locație (prima deschidere, fără permisiune)
    q=ctx(ask=True); q.goto(B+"/login"); q.get_by_label("Număr de telefon").fill("client@firma.ro"); q.get_by_label("Parolă").fill("parola1234"); q.get_by_role("button", name="Intră în aplicație").click(); q.wait_for_url(re.compile("/dashboard"))
    q.wait_for_timeout(1500)
    if q.get_by_text("Pornește notificările").count():  # apare doar când serverul are cheia de notificări (VAPID)
        q.screenshot(path="shots/88_cerere_notificari.png"); q.get_by_role("button", name="Mai târziu").click(); ok("la deschidere: cererea de notificări, apoi cea de locație")
    expect(q.get_by_text("Locația la deschiderea aplicației")).to_be_visible(); q.screenshot(path="shots/86_cerere_locatie.png")
    q.get_by_role("button", name="Nu acum").click(); expect(q.get_by_text("Locația la deschiderea aplicației")).to_have_count(0)
    q.reload(); q.wait_for_timeout(1500); expect(q.get_by_text("Locația la deschiderea aplicației")).to_have_count(0); ok("cererea de locație: explicație, „Nu acum” nu mai deranjează")
    # anunț pentru toate firmele + notificare pe ecran
    c.goto(B+"/dashboard"); expect(c.get_by_role("heading", name="Lucrări active")).to_be_visible(); c.wait_for_timeout(800)
    o.get_by_role("tab", name="Anunțuri").click()
    o.get_by_label("Titlu").fill("Mentenanță duminică"); o.get_by_label("Mesaj (opțional)").fill("Aplicația nu va fi disponibilă între 22:00 și 23:00.")
    o.get_by_label("Tip").select_option("warning"); o.get_by_role("button", name="Publică anunțul").click()
    expect(o.get_by_text("Anunț publicat și trimis ca notificare tuturor.")).to_be_visible(); expect(o.get_by_text("Anunț activ acum")).to_be_visible()
    o.screenshot(path="shots/77_proprietar_anunturi.png", full_page=True)
    c.evaluate("window.dispatchEvent(new Event('focus'))")
    expect(c.locator("[aria-live=polite]").get_by_text("Mentenanță duminică")).to_be_visible()
    c.screenshot(path="shots/78_notificare_pe_ecran.png"); ok("notificarea apare pe ecran la client")
    c.reload(); expect(c.get_by_text("Aplicația nu va fi disponibilă între 22:00 și 23:00.")).to_be_visible()
    c.screenshot(path="shots/79_anunt_la_client.png"); ok("anunțul apare sus la toate firmele")
    c.get_by_role("button", name="Închide anunțul").click(); c.reload(); expect(c.get_by_text("Aplicația nu va fi disponibilă între 22:00 și 23:00.")).to_have_count(0)
    ok("clientul poate închide anunțul")
    o.get_by_role("button", name="Oprește").click(); expect(o.get_by_text("Anunț activ acum")).to_have_count(0)
