    o.get_by_role("tab", name="Firme").click(); o.locator("main").get_by_role("button").filter(has_text="Test srl").first.click()
    o.get_by_role("button", name="Suspendă firma").click(); expect(o.get_by_role("button", name="Reactivează firma")).to_be_visible()
    o.goto(B+"/"); o.wait_for_url(re.compile("/proprietar")); expect(o.get_by_role("heading", name="Panoul proprietarului")).to_be_visible()
