    expect(o.get_by_role("link", name="Planning")).to_have_count(0); expect(o.get_by_role("link", name="Notificări").first).to_be_visible()
    o.screenshot(path="shots/82_doar_proprietar.png", full_page=True); ok("firma proprie suspendată → contul rămâne doar cu panoul de proprietar")
